-- Seed data para competencias específicas de 4to Grado del Nivel Secundario
-- Documento oficial: Adecuación Curricular Nivel Secundario - Segundo Ciclo (4to Grado)

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española
('Secundaria', '4to', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Emplea adecuadamente un género textual, siguiendo los procesos de compresión y producción oral y escrita con creatividad, así como el uso de las TIC y otros recursos y medios, al comunicarse en diferentes contextos.'),
('Secundaria', '4to', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Usa secuencias argumentativas (hechos, ejemplos, analogías, argumentos y contraargumentos), en discursos orales y escritos, abordados con temas sociales de su realidad y fuera de esta.'),
('Secundaria', '4to', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Describe problemas de su vida familiar, estudiantil y social, utilizando un tipo de texto como el informe de investigación, en el punto de partida para su estudio y aporte de posibles soluciones.'),
('Secundaria', '4to', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Sintetiza a través de textos variados relaciones socioculturales de entornos diversos, valorando las propiedades naturales que ponen de relieve hechos y tradiciones históricas.'),
('Secundaria', '4to', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Evidencia conocimiento y comprensión de sí mismo y de los demás, expresando su percepción del mundo, mediante un tipo de texto adecuado a las situaciones personales y sociales.'),
('Secundaria', '4to', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Explica conocimientos de procesos investigativos científicos y del uso de tecnología, a través de textos de secuencia expositivo-explicativa, acorde con su grado y las necesidades contextuales.'),
('Secundaria', '4to', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Manifiesta conocimientos y experiencia sobre situaciones relacionadas con salud, medioambiente y la comunidad, mediante textos de secuencias y géneros variados, a través de herramientas tecnológicas y otros medios y recursos.'),

-- Lenguas Extranjeras - Inglés
('Secundaria', '4to', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Interactúa en el idioma inglés de forma sostenida y comprensible, utilizando una estructura sencilla del discurso en distintas situaciones de comunicación para informar, dar instrucciones, narrar, opinar, expresar planes futuros y explicar problemas sobre aspectos de la vida diaria y temas que le son familiares o de su interés.'),
('Secundaria', '4to', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Interactúa de forma sencilla en el idioma inglés en distintas situaciones de comunicación sobre temas habituales, utilizando una estructura lógica y creativa en el discurso donde se expresan opiniones, se hacen predicciones y se relatan experiencias, empleando estrategias de desempeño comunicativo.'),
('Secundaria', '4to', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Describe situaciones y problemas de su entorno inmediato y su vida diaria de forma sencilla, detallada y comprensible para facilitar la solución y el abordaje de éstos, compartiendo informaciones, ideas, razonamientos y puntos de vista, motivos, planes e instrucciones en el idioma inglés.'),
('Secundaria', '4to', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se relaciona con las demás personas con cortesía, respeto e integridad, valorando las diferencias individuales y la identidad social y cultural local y de otros países al comunicarse en el idioma inglés, de forma oral y escrita.'),
('Secundaria', '4to', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Se comunica en el idioma inglés con cortesía, honestidad y actitud de respeto al expresar o escuchar opiniones, deseos, relato de experiencias y planes futuros.'),
('Secundaria', '4to', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Localiza, organiza y comparte información pertinente en formato físico, digital o virtual sobre temas de carácter científico y tecnológico propios de su contexto cotidiano o de situaciones de su interés.'),
('Secundaria', '4to', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Comunica preferencia de estilos de vida saludables y cuidado del medioambiente, en distintas situaciones sencillas de comunicación en inglés oral y escrito.'),

-- Lenguas Extranjeras - Francés
('Secundaria', '4to', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación, utilizando el idioma francés con frases y oraciones básicas, con la intención de comprar, solicitar y ofrecer información sobre servicios en una ciudad, estados físicos, de ánimo y de salud, relativos a necesidades inmediatas y a temas cotidianos.'),
('Secundaria', '4to', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Se comunica en el idioma francés de forma muy breve y sencilla en distintas situaciones de comunicación sobre necesidades inmediatas y temas cotidianos, utilizando el pensamiento lógico verbal, la creatividad y un espíritu observador, necesitando ayuda al expresarse y esfuerzo del interlocutor para ser comprendido.'),
('Secundaria', '4to', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Comprende y expresa informaciones relevantes para resolver situaciones y problemas de su entorno cotidiano y necesidades inmediatas de comunicación, con la finalidad de compartir información personal, estados de salud físicos y anímicos, sentimientos, servicios en la ciudad y comprar, utilizando frases y oraciones muy breves y sencillas.'),
('Secundaria', '4to', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE-LEF4', 'Se comunica de forma oral y escrita, con cortesía, respeto, honestidad y asertividad, en intercambios muy sencillos en francés, identificando las diferencias individuales y la identidad social y cultural propia y de otros países con la finalidad solicitar y ofrecer información personal, estados de salud, físicos y necesidades, así como servicios en la ciudad y compras.'),
('Secundaria', '4to', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Se comunica en el idioma francés, en intercambios muy sencillos, con cortesía, honestidad, asertividad y actitud de respeto, aceptación y cuidado de sí mismo/a y de las demás personas en situaciones diversas de la vida cotidiana.'),
('Secundaria', '4to', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Identifica, organiza y comparte en formato físico, digital o en línea, información relativa a la ciencia y la tecnología presentes en su entorno cotidiano, al describir estados de salud, anímicos y físicos e informar sobre servicios y compras, haciendo uso de vocabulario limitado y oraciones muy breves y sencillas.'),
('Secundaria', '4to', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Expresa preferencia por opciones que impactan positivamente la salud propia y de otras personas, el medio ambiente y su entorno próximo, en distintas situaciones concretas de comunicación oral y escrita, con la finalidad de compartir información personal, estados de salud físicos y anímicos, sentimientos y servicios en la ciudad y comprar, utilizando frases y oraciones muy breves y sencillas.'),

-- Matemática
('Secundaria', '4to', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Comprende la matemática leída en textos apropiados a su nivel de desarrollo, formulando preguntas de aclaración y ampliación, para clasificar conceptos y relaciones matemáticas.'),
('Secundaria', '4to', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-MAT2', 'Construye argumentos sencillos haciendo uso de sus conocimientos y de reglas de razonamiento lógico para dar validez a las propias ideas matemáticas.'),
('Secundaria', '4to', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE-MAT3', 'Aplica estrategias integradas de resolución de problemas para investigar y entender conceptos matemáticos.'),
('Secundaria', '4to', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Transmite asertivamente los propios puntos de vista para generar opciones creativas frente a la interpretación de situaciones matemáticas respetando las diferentes propuestas de los demás.'),
('Secundaria', '4to', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Muestra relaciones positivas en el trabajo matemático, en equipo, aportando soluciones frente a situaciones problemáticas relativas a la comunidad.'),
('Secundaria', '4to', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Utiliza herramientas tecnológicas para la resolución de problemas y situaciones matemáticas diversas.'),
('Secundaria', '4to', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Emplea sus conocimientos matemáticos conectándolos con otras áreas y disciplinas para comprender los fenómenos naturales que afectan el medioambiente.'),

-- Ciencias Sociales
('Secundaria', '4to', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Analiza en fuentes primarias y secundarias procesos sociales, políticos, económicos, históricos, geográficos o culturales, con la finalidad de elaborar proyectos fundamentados en información verificable y confiable.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Reconoce a través de propuestas o proyectos de investigación, hechos históricos ocurridos en diferentes periodos con el espacio geográfico; con la finalidad de desarrollar una conciencia crítica sobre los cambios económicos, políticos, sociales y culturales que se produjeron en el tiempo y el espacio.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Relaciona en investigaciones y producciones la existencia de un problema y situaciones que se presentan; con la finalidad de ubicarlos en un espacio y tiempo determinado.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Utiliza habilidades y conocimientos adquiridos al promover la convivencia democrática en cualquier contexto y en la defensa de los valores culturales e interculturales; con la finalidad de fomentar el respeto por la Constitución y los derechos humanos.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Valora la importancia de las relaciones basadas en el respeto entre las personas y la sociedad en general, con la finalidad de fomentar una convivencia armoniosa en la que se promueva el bienestar común.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Compara informaciones científicas sobre teorías relacionadas con fenómenos naturales y sociales, a través del uso de la tecnología, con la finalidad de ofrecer explicaciones claras de los datos obtenidos.'),
('Secundaria', '4to', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Examina la importancia de un estilo de vida saludable y el cuidado de su entorno natural y social; con la finalidad de garantizar un ambiente saludable.'),

-- Ciencias de la Naturaleza – Biología
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el lenguaje científico y tecnológico fundamental de la biología que implica ideas, leyes, modelos y procesos.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones y estrategias científicas y tecnológicas a problemas y fenómenos naturales relacionados con los fundamentos de la Biología.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica diversos procedimientos científicos y tecnológicos para solucionar problemas o dar respuestas a fenómenos naturales relacionados con los fundamentos de la Biología.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza críticamente la naturaleza y filosofía de la biología, bioingenierías y bioinformática, sus aportes, alcance del desarrollo tecnológico en nuestra sociedad y la bioética en la investigación.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal y profesional desde la biología, biotecnología.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones, y construye una explicación utilizando conceptos, modelos, leyes, teorías y procesos fundamentales de la biología y la biotecnología.'),
('Secundaria', '4to', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Asume y actúa con responsabilidad crítica y autónoma para un desarrollo sostenible, cuidado ambiental y su salud, basadas en las ideas y teorías de la biología.'),

-- Educación Artística
('Secundaria', '4to', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Reconoce elementos identitarios y culturales, utilizando elementos de los lenguajes artísticos al comunicar sus expectativas, significados y valores.'),
('Secundaria', '4to', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Genera ideas, propuestas y mensajes, utilizando procesos propios de los lenguajes artísticos.'),
('Secundaria', '4to', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Comprende el arte como medio para dar soluciones creativas a necesidades expresivas.'),
('Secundaria', '4to', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Comprende su responsabilidad social, política y cultural al comunicarse de un modo creativo para influir en la mejora de su contexto.'),
('Secundaria', '4to', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Valora la diversidad cultural y respeta a las demás personas y como estas se manifiestan en las diferentes formas de expresión artística.'),
('Secundaria', '4to', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Aplica métodos, técnicas y procesos de diferentes lenguajes artísticos expresando ideas y mensajes.'),
('Secundaria', '4to', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Reconoce la importancia del arte y la cultura, al crear obras y proyectos que impacten en la protección del medioambiente y la salud propia y colectiva.'),

-- Educación Física
('Secundaria', '4to', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Comunica su estado de ánimo y emociones a partir de la noción de su esquema corporal, a los fines de mostrar la conciencia de su propio cuerpo.'),
('Secundaria', '4to', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Realiza cambios sencillos en su acción motriz, a partir de su percepción y apreciación de variación de patrones, tamaños, formas, direcciones y relaciones espaciales en diversos entornos.'),
('Secundaria', '4to', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Relaciona las reglas y los elementos técnicos deportivos con situaciones de la vida cotidiana, a fin de alcanzar los niveles adecuados de eficacia motora progresiva.'),
('Secundaria', '4to', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Realiza acciones motrices específicas colectivas, estableciendo relaciones de cooperación y/u oposición, a fin de favorecer el disfrute de las actividades físicas en el grupo, mediante el respeto a las diferencias individuales.'),
('Secundaria', '4to', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Reconoce sus limitaciones y potencialidades corporales y motrices en diversas situaciones físicas, mostrando motivación y disponibilidad para el disfrute de la actividad motriz y el juego para alcanzar el bienestar propio y colectivo.'),
('Secundaria', '4to', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Propone algunas variantes en la normativa y organización del juego, a partir del conocimiento básico de las técnicas, condiciones del terreno y los implementos a utilizar, con el uso de herramientas tecnológicas.'),
('Secundaria', '4to', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Interpreta los cambios físicos que le permiten el reconocimiento corporal y su eficiencia motora con la introducción de secuencias de movimientos, en una relación armónica saludable con su cuerpo y el entorno que le rodea.'),

-- Formación Integral Humana y Religiosa
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Plantea la importancia de construir relaciones de paz y de respeto ante situaciones personales, familiares, sociales, culturales y religiosas a fin de resolver los conflictos interpersonales en su vida cotidiana.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Se interroga y busca respuestas sobre el sentido de la vida, a partir de las enseñanzas de Jesús de Nazaret a fin de fundamentar en principios y valores su realización personal.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Formula alternativas a situaciones, problemáticas y conflictos personales y familiares, tomando como referencia actitudes y valores de Jesús de Nazaret, a fin de fomentar relaciones armoniosas en su contexto familiar.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Plantea el trabajo como participación y desarrollo de la obra creadora de Dios, a fin identificar su contribución en la realización personal y en el progreso de la sociedad.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Constata la universalidad del hecho religioso como apertura a la trascendencia en su contexto, a fin de reconocer el fenómeno religioso en cada cultura y asumir una postura de respeto ante las creencias de los demás.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Aplica criterios éticos en el uso de las tecnologías de la información y la comunicación, a fin de favorecer la calidad de vida y la convivencia armónica en los diferentes contextos.'),
('Secundaria', '4to', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Implementa acciones en favor de una ecología humana y se siente parte de ella como criatura de Dios, a fin de aportar con el desarrollo sostenible que garantice el bienestar social.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) 
DO UPDATE SET 
    codigo = EXCLUDED.codigo,
    descriptor = EXCLUDED.descriptor,
    bloque = EXCLUDED.bloque,
    updated_at = NOW();
